LESSONS = {'Nun i tenvin': 'Nun and tanwin', 'Mim sākin': 'Mim sakin', 'Dužine': 'Lengthening (madd)', 'Idgam mislejn': 'Idgham mithlayn',
           'Hukmu-r-Rā’': 'The rules of Ra', 'Damir': 'Damir (the pronoun)', 'Kalkala': 'Qalqalah', 'Lafzatullah': 'Lafz al-Jalalah'}

_NO_WORDS = re.compile(r'^[؀-ۿ\s\d+–/.-]*$')   # Arabic examples, letters and numbers stay as they are


def english_q(q):
    for bs, en in SUFFIXES:
        if q.endswith(bs):
            return english_q(q[:-len(bs)]) + en
    for pat, en in _COMPILED:
        m = pat.match(q)
        if m:
            return en.format(*m.groups())
    raise AssertionError(f'tajwid question not in the templates: {q!r}')


def english_opt(o):
    if _NO_WORDS.match(o):
        return o
    assert o in OPTIONS, f'tajwid answer not translated: {o!r}'
    return OPTIONS[o]
